select 
from t_order_info
where user_id = #{userId}
order by create_time desc
limit #{limit} offset #{offset}

select count(*)
from t_order_info
where user_id = #{userId}

select 
from t_order_info
where id = (
select id
from (
select id
from t_order_info
where product_id = #{productId}
and payment_type = #{paymentType}
and legacy_status = #{orderStatus}


    and payment_app_id = #{paymentAppId}


    and payment_app_id is null


order by create_time desc, id desc
) latest_order
where rownum <= 1
)

mapper.update:
update t_order_info
set pay_status = 'PAYING',
update_time = CURRENT_TIMESTAMP

  , fence_token = #{fenceToken}

where order_no = #{orderNo}
and pay_status = 'UNPAID'

  and fence_token  <=  #{fenceToken}

update t_order_info
set order_status = 'ACTIVE',
pay_status = 'PAID',
paid_amount = #{paidAmount},
paid_time = CURRENT_TIMESTAMP,
update_time = CURRENT_TIMESTAMP

  , fence_token = #{fenceToken}

where order_no = #{orderNo}
and order_status = 'WAIT_PAY'

  and fence_token  <=  #{fenceToken}

update t_order_info
set order_status = 'CLOSED',
pay_status = 'UNPAID',
fulfillment_status = 'CANCELLED',
update_time = CURRENT_TIMESTAMP

  , fence_token = #{fenceToken}

where order_no = #{orderNo}
and order_status = 'WAIT_PAY'

  and fence_token  <=  #{fenceToken}

update t_order_info
set refund_frozen_amount = refund_frozen_amount + #{amount}, update_time = CURRENT_TIMESTAMP

  , fence_token = #{fenceToken}

where order_no = #{orderNo}
and paid_amount - refunded_amount - refund_frozen_amount  >=  #{amount}

  and fence_token  <=  #{fenceToken}

update t_order_info
set refund_frozen_amount = refund_frozen_amount - #{amount}, update_time = CURRENT_TIMESTAMP

  , fence_token = #{fenceToken}

where order_no = #{orderNo}
and refund_frozen_amount  >=  #{amount}

  and fence_token  <=  #{fenceToken}

update t_order_info
set refund_frozen_amount = refund_frozen_amount - #{amount},
refunded_amount = refunded_amount + #{amount},
update_time = CURRENT_TIMESTAMP

  , fence_token = #{fenceToken}

where order_no = #{orderNo}
and refund_frozen_amount  >=  #{amount}

  and fence_token  <=  #{fenceToken}

update t_order_info o set o.refund_status = ( select case when coalesce(sum(i.refund_frozen_amount), 0) > 0 then 'REFUNDING' when coalesce(sum(i.refunded_amount), 0) <= 0 then 'NONE' when coalesce(sum(i.refunded_amount), 0) >= o.paid_amount then 'FULL_REFUNDED' else 'PARTIAL_REFUNDED' end from t_order_item i where i.order_no = o.order_no ), o.update_time = CURRENT_TIMESTAMP
, o.fence_token = #{fenceToken}
where o.order_no = #{orderNo}
and o.fence_token <= #{fenceToken}
